package observer

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"time"

	"github.com/goalforge/goalforge/internal/gitops"
	"github.com/goalforge/goalforge/internal/standards"
	store "github.com/goalforge/goalforge/internal/store/sqlite"
)

// ProjectTick is what one unattended pass did for one project.
type ProjectTick struct {
	ProjectID, ProjectName string
	Decision               Decision
	Ran                    bool
	Filed                  []string
	Approved               []string
	Merged                 []string
	// Note carries the one-line reason when nothing happened, and Err when
	// something went wrong. They are separate because "nothing was due" is a
	// healthy tick and a failure is not, and a loop that logged them the same
	// way would make a broken project invisible among the quiet ones.
	Note string
	Err  error
}

// TickResult is one sweep across every project in the program.
type TickResult struct {
	Projects []ProjectTick
}

// Acted reports whether the sweep changed anything, so a caller can stay quiet
// when it did not.
func (r TickResult) Acted() bool {
	for _, project := range r.Projects {
		if project.Ran || len(project.Approved) > 0 || len(project.Merged) > 0 || project.Err != nil {
			return true
		}
	}
	return false
}

// Tick runs the supply and autonomy loop across every project in the program,
// once.
//
// It exists because everything the schedule is built from — a daily interval, a
// discovery budget, an idempotency key that survives two workers seeing the
// same commit — is machinery for something that runs while nobody is watching.
// Until something calls it on a timer, all of it describes a loop that only
// turns when a person types a command, which is the one situation none of it
// was for.
func Tick(ctx context.Context, db *store.Store, toolVersion string, detectors []Detector,
	schedule SchedulePolicy, supply SupplyPolicy) (TickResult, error) {
	var result TickResult
	projects, err := db.ListProjects(ctx)
	if err != nil {
		return result, err
	}
	sort.SliceStable(projects, func(i, j int) bool { return projects[i].ID < projects[j].ID })
	for _, project := range projects {
		profile, _, profileErr := db.StandardProfile(ctx, project.ID)
		if errors.Is(profileErr, store.ErrNotFound) {
			// Not in the program. A project that never pinned a pack has not
			// asked to be maintained and must not be touched.
			continue
		}
		if profileErr != nil {
			return result, profileErr
		}
		tick := tickProject(ctx, db, project.ID, project.Name, project.RepositoryPath,
			project.DefaultBranch, toolVersion, profile, detectors, schedule, supply)
		result.Projects = append(result.Projects, tick)
	}
	return result, nil
}

// tickProject is one project's turn.
//
// Every failure is captured rather than returned, so one project's missing
// repository does not stop the sweep. An unattended loop that aborts on the
// first problem stops maintaining every project because of one — and the one
// that broke it is the one nobody was watching.
func tickProject(ctx context.Context, db *store.Store, projectID, name, repository, branch, toolVersion string,
	profile standards.Profile, detectors []Detector, schedule SchedulePolicy, supply SupplyPolicy) ProjectTick {
	tick := ProjectTick{ProjectID: projectID, ProjectName: name}
	pack, err := packFor(profile.PackRef)
	if err != nil {
		tick.Err = err
		return tick
	}
	// Drift is checked here and not only on the screens that display it. A
	// pack edited in place keeps its id@version, so it resolves by ref and no
	// revision bump marks anything stale — the project is simply judged by
	// criteria it never agreed to, and an unattended sweep is the one place
	// nobody would notice.
	//
	// Asked of the store rather than compared here. The rule about what counts
	// as drift — including that a project enrolled before checksums were
	// recorded has not drifted — lives in one place, and a second copy of it
	// is two rules waiting to disagree.
	drifted, err := db.PackDrift(ctx, projectID, pack)
	if err != nil {
		tick.Err = err
		return tick
	}
	if drifted {
		tick.Err = fmt.Errorf("고정한 팩 %s 의 체크섬이 다릅니다 — 이 빌드의 팩은 프로젝트가 동의한 것이 아닙니다. `goalforge standards profile --pack %s` 로 다시 고정하세요",
			profile.PackRef, profile.PackRef)
		return tick
	}
	head, err := gitops.HeadCommit(ctx, repository, branch)
	if err != nil {
		tick.Err = fmt.Errorf("저장소를 읽지 못했습니다: %w", err)
		return tick
	}
	goal, err := db.CurrentGoal(ctx, projectID)
	if errors.Is(err, store.ErrNotFound) {
		// Enrolling a project and setting its goal are separate commands, so a
		// project sits in this state for as long as it takes someone to run the
		// second one. There is nothing to supply work against, but nothing is
		// broken either — and calling it a failure makes the sweep print an
		// error every quarter of an hour, forever, about a project that only
		// needs a goal. The loop is the one place that cost compounds silently:
		// nobody is watching, so the noise is discovered as a habit of ignoring
		// the log.
		tick.Note = "목표가 아직 없습니다 — `goalforge goal set` 이후에 공급이 시작됩니다"
		return tick
	}
	if err != nil {
		tick.Err = fmt.Errorf("목표를 읽지 못했습니다: %w", err)
		return tick
	}
	pass, err := RunScheduledPass(ctx, db, PassRequest{ProjectID: projectID, GoalID: goal.ID,
		Repository: repository, HeadSHA: head, ToolVersion: toolVersion, Pack: pack, Profile: profile,
		Detectors: detectors, Schedule: schedule, Supply: supply})
	switch {
	case errors.Is(err, ErrDiscoveryBudgetSpent), errors.Is(err, ErrSupplyPaused):
		// Both are the loop working as configured, not a failure. Recording
		// them as errors would make a correctly throttled project look broken.
		tick.Note = err.Error()
	case err != nil:
		tick.Err = err
		return tick
	default:
		tick.Decision, tick.Ran = pass.Decision, pass.Ran
		tick.Filed = pass.Result.Filed
		if !pass.Ran && tick.Note == "" {
			tick.Note = pass.Detail
		}
	}
	config, err := db.AutonomyConfigFor(ctx, projectID)
	if err != nil && !errors.Is(err, store.ErrNotFound) {
		tick.Err = err
		return tick
	}
	// A project with no saved envelope gets the zero value, which is switched
	// off — an unattended loop reading a missing configuration as permission
	// is the worst possible reading of an absence. Whether an envelope permits
	// anything is AutoApprove's decision and is not repeated here: the same
	// rule in two places is two rules waiting to disagree.
	policy := AutonomyPolicy{Enabled: config.Enabled, AllowedStandards: config.AllowedStandards,
		AllStandards: config.AllStandards, AllowedScopes: config.AllowedScopes, AllScopes: config.AllScopes,
		MaxTokens: config.MaxTokens, DailyLimit: config.DailyLimit, AutoMerge: config.AutoMerge}
	execution, err := AutoApprove(ctx, db, projectID, goal.ID, policy)
	if err != nil {
		tick.Err = err
		return tick
	}
	tick.Approved = execution.Approved
	if !policy.AutoMerge {
		return tick
	}
	merges, err := AutoApproveMerges(ctx, db, projectID, goal.ID, policy)
	if err != nil {
		tick.Err = err
		return tick
	}
	tick.Merged = merges.Approved
	return tick
}

// packFor resolves a pinned pack reference.
//
// There is one shipped pack; a profile naming anything else is refused rather
// than silently measured against whatever happens to be compiled in.
func packFor(ref string) (standards.Pack, error) { return standards.ByRef(ref) }

var _ = time.Now

package observer

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	store "github.com/goalforge/goalforge/internal/store/sqlite"
)

// AutoApproveMerges grants the merge approvals the envelope allows.
//
// This is the point past which a change leaves the worktree and lands on the
// branch everyone else builds from, so what it requires is narrower than what
// approving execution requires: the work has to be finished, its gates have to
// have passed on the very commit being released, and the branch it is going
// into has to be working.
//
// The approval it writes is an ordinary scoped approval. It goes through the
// same request-and-grant path a person's does, lands in the same audit chain,
// and is pinned to the same commit — so `goalforge merge` cannot tell the
// difference, and neither can `integrity verify`. Nothing about the record
// degrades because a machine made it.
func AutoApproveMerges(ctx context.Context, db *store.Store, projectID, goalID string, policy AutonomyPolicy) (AutoDecisions, error) {
	decisions := AutoDecisions{Refused: map[string]string{}}
	if !policy.Enabled {
		decisions.Detail = "자동 승인이 켜져 있지 않습니다"
		return decisions, nil
	}
	if !policy.AutoMerge {
		// Turning on automatic execution is not the same decision as turning
		// on automatic release. Someone who wanted the first must not silently
		// get the second.
		decisions.Detail = "자동 병합 승인이 켜져 있지 않습니다"
		return decisions, nil
	}
	integration, err := db.IntegrationStatus(ctx, projectID)
	if err != nil {
		return decisions, err
	}
	if integration.LastSHA != "" && !integration.LastPassed {
		// The same rule `goalforge merge` enforces, applied a step earlier so
		// nothing is approved that would then be refused at the gate.
		decisions.Detail = "기본 브랜치의 통합 검증이 실패한 상태입니다 — 먼저 복구해야 합니다"
		return decisions, nil
	}
	findings, err := db.SuppliedFindings(ctx, projectID)
	if err != nil {
		return decisions, err
	}
	claims, err := db.GateClaims(ctx, projectID)
	if err != nil {
		return decisions, err
	}
	judgedBy := map[string][]string{}
	for checkType, claim := range claims {
		for _, standardID := range claim.Settles {
			judgedBy[standardID] = append(judgedBy[standardID], checkType)
		}
	}
	items, err := db.ListWorkItems(ctx, goalID)
	if err != nil {
		return decisions, err
	}
	project, err := db.ProjectByID(ctx, projectID)
	if err != nil {
		return decisions, err
	}
	ids := make([]string, 0, len(items))
	byID := map[string]int{}
	for i, item := range items {
		if item.Status != "DONE" {
			continue
		}
		if _, supplied := findings[item.ID]; !supplied {
			// Work a person wrote is not automation's to release.
			continue
		}
		ids = append(ids, item.ID)
		byID[item.ID] = i
	}
	sort.Strings(ids)
	// Releases already decided on. Collected rather than dropped, because
	// "nothing to approve" and "an approval is standing ready to spend" look
	// the same to an operator re-running the command and are not the same
	// thing: the second one is waiting for `goalforge merge`.
	var standing []string
	for _, workID := range ids {
		item := items[byID[workID]]
		standardID := findings[workID]
		gates := judgedBy[standardID]
		if reason := admits(policy, item, standardID, gates); reason != "" {
			decisions.Refused[workID] = reason
			continue
		}
		commit, err := db.LatestRunCommitForWork(ctx, projectID, workID)
		if errors.Is(err, store.ErrNotFound) {
			decisions.Refused[workID] = "검증된 커밋이 없습니다"
			continue
		}
		if err != nil {
			return decisions, err
		}
		if reason, err := gatesPassedOn(ctx, db, commit.RunID, gates); err != nil {
			return decisions, err
		} else if reason != "" {
			decisions.Refused[workID] = reason
			continue
		}
		scope := store.ApprovalScope{WorkItemID: workID, SourceBranch: commit.Branch,
			TargetRef: project.DefaultBranch, CommitSHA: commit.CommitSHA, FilesChanged: commit.FilesCommitted}
		// Nothing about finished work changes between two passes of the
		// unattended sweep, so without this the same release is approved again
		// every quarter of an hour: a stack of identical approvals, each one of
		// which `goalforge merge` will spend to release the same commit with no
		// review behind it, and a sweep that reports activity forever and so can
		// never be quiet again.
		//
		// This is not a second copy of the envelope — what the envelope permits
		// is admits()/AutoApprove's decision and is not repeated here. It asks
		// only whether this decision has already been taken, which is the same
		// question item.Status answers for execution approvals and which the
		// merge path has nothing to answer with, because merging does not move
		// the item off DONE.
		decided, err := db.ScopedApprovalExists(ctx, projectID, store.ApprovalMergeBranch, scope)
		if err != nil {
			return decisions, err
		}
		if decided {
			standing = append(standing, workID)
			continue
		}
		basis := fmt.Sprintf("자동 병합 승인 — 기준 %s · 게이트 %s · 커밋 %s",
			standardID, strings.Join(gates, ", "), shortSHA(commit.CommitSHA))
		approval, err := db.RequestScopedApproval(ctx, projectID, store.ApprovalMergeBranch, basis, scope)
		if err != nil {
			return decisions, err
		}
		if err = db.Approve(ctx, projectID, approval.ID); err != nil {
			return decisions, err
		}
		decisions.Approved = append(decisions.Approved, workID)
	}
	if len(standing) > 0 {
		decisions.Detail = fmt.Sprintf("이미 결정된 병합이라 다시 발급하지 않았습니다: %s", strings.Join(standing, ", "))
	}
	return decisions, nil
}

// gatesPassedOn reports why the gates that settle a criterion did not pass on
// the run that produced this commit.
//
// It reads the run's own results rather than the goal's latest, because the
// question is whether *this change* verified. A later run on a different work
// item passing tells nothing about this one.
func gatesPassedOn(ctx context.Context, db *store.Store, runID string, gates []string) (string, error) {
	results, err := db.VerificationsForRun(ctx, runID)
	if err != nil {
		return "", err
	}
	status := map[string]string{}
	for _, result := range results {
		status[result.CheckType] = result.Status
	}
	var missing, failed []string
	for _, checkType := range gates {
		switch state, ran := status[checkType]; {
		case !ran:
			missing = append(missing, checkType)
		case state != "PASSED":
			failed = append(failed, checkType+"="+state)
		}
	}
	sort.Strings(missing)
	sort.Strings(failed)
	if len(failed) > 0 {
		return "게이트가 통과하지 않았습니다: " + strings.Join(failed, ", "), nil
	}
	if len(missing) > 0 {
		// A gate that did not run on this change has not judged it. Releasing
		// on the strength of a gate nobody executed is releasing unverified.
		return "이 변경에서 돌지 않은 게이트가 있습니다: " + strings.Join(missing, ", "), nil
	}
	return "", nil
}

func shortSHA(sha string) string {
	if len(sha) > 12 {
		return sha[:12]
	}
	return sha
}

var _ = time.Now

