// Package procctl provides platform-specific process-group control so the
// orchestrator can signal an AI CLI process together with every child it
// spawned.
package procctl

import (
	"os/exec"
	"strconv"
	"syscall"
)

var (
	kernel32                     = syscall.NewLazyDLL("kernel32.dll")
	procGenerateConsoleCtrlEvent = kernel32.NewProc("GenerateConsoleCtrlEvent")
)

// SetGroup starts cmd in a new process group so console control events target
// the whole tree instead of the orchestrator itself.
func SetGroup(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{CreationFlags: syscall.CREATE_NEW_PROCESS_GROUP}
}

// KillGroup forcibly terminates cmd's process tree. taskkill /T covers child
// processes that a plain Process.Kill would orphan.
func KillGroup(cmd *exec.Cmd) error {
	if cmd.Process == nil {
		return nil
	}
	kill := exec.Command("taskkill", "/T", "/F", "/PID", strconv.Itoa(cmd.Process.Pid))
	if err := kill.Run(); err != nil {
		return cmd.Process.Kill()
	}
	return nil
}

// InterruptGroup sends CTRL_BREAK to cmd's process group, the closest Windows
// analogue of SIGINT for a graceful stop.
func InterruptGroup(cmd *exec.Cmd) error {
	if cmd.Process == nil {
		return nil
	}
	r, _, err := procGenerateConsoleCtrlEvent.Call(uintptr(syscall.CTRL_BREAK_EVENT), uintptr(cmd.Process.Pid))
	if r == 0 {
		return err
	}
	return nil
}
// Package testscript writes small fake executables for tests so provider
// adapters and verification gates can be exercised on both Unix and Windows.
package testscript

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// Write creates an executable script at dir/name and returns its path. posix
// is a /bin/sh body and windows is a cmd.exe body (without the @echo off
// prefix); the variant matching the current platform is written. On Windows
// the file gets a .cmd extension so the OS can execute it directly.
func Write(t testing.TB, dir, name, posix, windows string) string {
	t.Helper()
	var path string
	var body []byte
	if runtime.GOOS == "windows" {
		path = filepath.Join(dir, name+".cmd")
		body = []byte("@echo off\r\n" + strings.ReplaceAll(windows, "\n", "\r\n") + "\r\n")
	} else {
		path = filepath.Join(dir, name)
		body = []byte("#!/bin/sh\n" + posix + "\n")
	}
	if err := os.WriteFile(path, body, 0o700); err != nil {
		t.Fatal(err)
	}
	return path
}

// WriteGo compiles a Go program into an executable at dir/name and returns its
// path.
//
// A fake written twice — once as a shell script, once as a batch file — is two
// programs that drift. One of the batch halves in this repository did nothing
// at all: it exited zero without writing the file or emitting the events its
// POSIX twin produced, so the test that depended on it could not have passed
// on Windows and nobody found out until the checks ran there. A compiled
// program is one program, and it behaves the same everywhere.
//
// Use Write for a fake whose two bodies are genuinely equivalent (`exit 0`);
// use this one as soon as the fake has to do something.
func WriteGo(t testing.TB, dir, name, source string) string {
	t.Helper()
	build := t.TempDir()
	if err := os.WriteFile(filepath.Join(build, "main.go"), []byte(source), 0o600); err != nil {
		t.Fatal(err)
	}
	output := filepath.Join(dir, name)
	if runtime.GOOS == "windows" {
		output += ".exe"
	}
	cmd := exec.Command("go", "build", "-o", output, filepath.Join(build, "main.go"))
	cmd.Dir = build
	if combined, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build fake %s: %v\n%s", name, err, combined)
	}
	return output
}

// kindChecks reports criteria whose proof cannot come from the gate that is
// supposed to measure them. A criterion asking whether the user can save their
// work, measured by a compile, is a configuration that reports success and
// ships a stub — and unlike a missing gate it looks completely healthy.
func kindChecks(input ReadinessInput) []Check {
	gateKinds := make(map[string]string, len(input.Gates))
	for _, gate := range input.Gates {
		gateKinds[gate.Type] = gate.Kind
	}
	var mismatched []string
	demanded := 0
	for _, criterion := range input.Criteria {
		required := input.CriterionKinds[criterion]
		if required == "" {
			continue
		}
		demanded++
		gateKind, covered := gateKinds[criterion]
		if !covered {
			// Already reported by the coverage check; saying it twice buries
			// the finding that is only visible here.
			continue
		}
		if !policy.EvidenceSatisfies(required, gateKind) {
			label := gateKind
			if label == "" {
				label = "종류 미지정"
			}
			mismatched = append(mismatched, fmt.Sprintf("%s (%s 필요, 게이트는 %s)", criterion, required, label))
		}
	}
	if len(mismatched) > 0 {
		sort.Strings(mismatched)
		return []Check{{Level: LevelFail, Name: "proof kind",
			Detail: "완료 조건이 요구하는 검증 종류와 게이트가 다릅니다: " + strings.Join(mismatched, ", ") + " (verify gate add --kind 로 게이트 종류를 바로잡거나 알맞은 게이트로 바꾸세요)"}}
	}
	if demanded > 0 {
		return []Check{{Level: LevelOK, Name: "proof kind",
			Detail: fmt.Sprintf("검증 종류를 요구하는 완료 조건 %d개가 알맞은 게이트로 측정됩니다", demanded)}}
	}
	// Nothing demanded a kind. If no gate claims to do more than compile, the
	// project can complete with a feature that was never exercised.
	behavioural := false
	for _, gate := range input.Gates {
		if gate.Kind != "" && gate.Kind != policy.KindBuild && gate.Kind != policy.KindReview {
			behavioural = true
			break
		}
	}
	if behavioural {
		return nil
	}
	return []Check{{Level: LevelWarn, Name: "proof kind",
		Detail: "동작을 확인하는 게이트가 없어 빌드만 통과해도 완료로 판정될 수 있습니다 (verify gate add --kind journey 와 goal set --criterion 이름@journey=true)"}}
}

