package diagnostics

import (
	"strings"
	"testing"
)

func levelFor(checks []Check, name string) string {
	for _, check := range checks {
		if check.Name == name {
			return check.Level
		}
	}
	return ""
}

// The configuration that looks healthy and never completes: a criterion with
// no gate of the same name can never accumulate evidence.
func TestReadinessCatchesUnmeasurableCriteria(t *testing.T) {
	input := ReadinessInput{
		HasProject: true,
		GoalTitle:  "ship",
		Criteria:   []string{"build_passed", "latency_p95"},
		Gates: []GateSpec{
			{Type: "build_passed", Command: []string{"go"}, Required: true},
		},
		BudgetConfigured: true,
	}
	checks := CheckReadiness(input)
	if levelFor(checks, "criteria coverage") != LevelFail {
		t.Fatalf("an unmeasurable criterion must block: %+v", checks)
	}
	for _, check := range checks {
		if check.Name == "criteria coverage" && !strings.Contains(check.Detail, "latency_p95") {
			t.Fatalf("the check must name the criterion: %q", check.Detail)
		}
	}
	input.Gates = append(input.Gates, GateSpec{Type: "latency_p95", Command: []string{"go"}, Required: true})
	if levelFor(CheckReadiness(input), "criteria coverage") != LevelOK {
		t.Fatal("covering the criterion must clear the finding")
	}
}

func TestReadinessBlocksConfigurationsThatCannotFinish(t *testing.T) {
	for _, tc := range []struct {
		name  string
		input ReadinessInput
		check string
	}{
		{"no goal", ReadinessInput{HasProject: true}, "goal"},
		{"no criteria", ReadinessInput{HasProject: true, GoalTitle: "g"}, "criteria"},
		{"no gates", ReadinessInput{HasProject: true, GoalTitle: "g", Criteria: []string{"build_passed"}}, "gates"},
		{"no required gate", ReadinessInput{HasProject: true, GoalTitle: "g", Criteria: []string{"build_passed"},
			Gates: []GateSpec{{Type: "build_passed", Command: []string{"go"}}}}, "gates"},
		{"missing command", ReadinessInput{HasProject: true, GoalTitle: "g", Criteria: []string{"build_passed"},
			Gates: []GateSpec{{Type: "build_passed", Command: []string{"goalforge-not-a-real-binary"}, Required: true}}}, "gate commands"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if level := levelFor(CheckReadiness(tc.input), tc.check); level != LevelFail {
				t.Fatalf("%s should be FAIL, got %q in %+v", tc.check, level, CheckReadiness(tc.input))
			}
		})
	}
}

// Readiness says nothing about a directory with no project: that is the
// environment check's job, and duplicating it would report the same problem
// twice with different wording.
func TestReadinessIsSilentWithoutAProject(t *testing.T) {
	if checks := CheckReadiness(ReadinessInput{}); len(checks) != 0 {
		t.Fatalf("checks=%+v", checks)
	}
}

// Things that need attention but do not make completion impossible are
// warnings, so a green doctor still means "this can finish".
func TestReadinessWarnsWithoutBlocking(t *testing.T) {
	input := ReadinessInput{HasProject: true, GoalTitle: "g", Criteria: []string{"build_passed"},
		Gates:              []GateSpec{{Type: "build_passed", Command: []string{"go"}, Required: true}},
		IntegrationPending: true, IntegrationReason: "병합 후", StaleCriteria: []string{"build_passed"}}
	checks := CheckReadiness(input)
	for _, name := range []string{"budget", "integration", "evidence"} {
		if levelFor(checks, name) != LevelWarn {
			t.Errorf("%s should warn, got %q", name, levelFor(checks, name))
		}
	}
	for _, check := range checks {
		if check.Level == LevelFail {
			t.Errorf("nothing here makes completion impossible: %+v", check)
		}
	}
}

// The misconfiguration that looks healthiest: a criterion about whether the
// user's task works, measured by a gate that only compiles. Every other check
// is green, so readiness has to be the thing that says it.
func TestReadinessRejectsProofOfTheWrongKind(t *testing.T) {
	input := ReadinessInput{
		HasProject:       true,
		GoalTitle:        "notes",
		Criteria:         []string{"note_saves"},
		CriterionKinds:   map[string]string{"note_saves": "journey"},
		Gates:            []GateSpec{{Type: "note_saves", Command: []string{"go"}, Required: true, Kind: "build"}},
		BudgetConfigured: true,
	}
	if level := levelFor(CheckReadiness(input), "proof kind"); level != LevelFail {
		t.Fatalf("a build gate behind a journey criterion must block: %+v", CheckReadiness(input))
	}
	input.Gates[0].Kind = "journey"
	if level := levelFor(CheckReadiness(input), "proof kind"); level != LevelOK {
		t.Fatalf("a journey gate behind a journey criterion is fine: %+v", CheckReadiness(input))
	}
}

// The same misconfiguration one rung lower, and the one an AI session reaches
// for on its own: a gate that reports its judgement of the change standing
// behind a criterion that asked for the change to build. Readiness has to say
// so before the run, because afterwards it looks like proof.
func TestReadinessRejectsAJudgementBehindAnObjectiveCriterion(t *testing.T) {
	input := ReadinessInput{
		HasProject:       true,
		GoalTitle:        "service",
		Criteria:         []string{"build_passed"},
		CriterionKinds:   map[string]string{"build_passed": "build"},
		Gates:            []GateSpec{{Type: "build_passed", Command: []string{"go"}, Required: true, Kind: "review"}},
		BudgetConfigured: true,
	}
	if level := levelFor(CheckReadiness(input), "proof kind"); level != LevelFail {
		t.Fatalf("a review gate behind a build criterion must block: %+v", CheckReadiness(input))
	}
	input.Gates[0].Kind = "build"
	if level := levelFor(CheckReadiness(input), "proof kind"); level != LevelOK {
		t.Fatalf("a build gate behind a build criterion is fine: %+v", CheckReadiness(input))
	}
}

// A project whose gates only compile can complete without anything ever having
// been exercised. That is a warning rather than a failure: it can still finish,
// just on weaker evidence than the user probably thinks.
func TestReadinessWarnsWhenNothingChecksBehaviour(t *testing.T) {
	input := ReadinessInput{
		HasProject: true, GoalTitle: "svc", Criteria: []string{"build_passed"}, BudgetConfigured: true,
		Gates: []GateSpec{{Type: "build_passed", Command: []string{"go"}, Required: true, Kind: "build"}},
	}
	if level := levelFor(CheckReadiness(input), "proof kind"); level != LevelWarn {
		t.Fatalf("build-only verification must be called out: %+v", CheckReadiness(input))
	}
	input.Gates = append(input.Gates, GateSpec{Type: "tests_passed", Command: []string{"go"}, Required: true, Kind: "test"})
	if level := levelFor(CheckReadiness(input), "proof kind"); level != "" {
		t.Fatalf("a project that exercises its code needs no warning: %+v", CheckReadiness(input))
	}
}

package sqlite

import (
	"context"
	"path/filepath"
	"testing"
	"time"

	"github.com/goalforge/goalforge/internal/model"
)

func proofKindProject(t *testing.T) (context.Context, *Store, model.Project) {
	t.Helper()
	ctx := context.Background()
	s, err := Open(filepath.Join(t.TempDir(), "state.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	p := model.Project{ID: "PRJ-1", Name: "demo", RepositoryPath: "/repo", DefaultBranch: "main", Provider: "codex"}
	if err = s.CreateProject(ctx, p); err != nil {
		t.Fatal(err)
	}
	return ctx, s, p
}

// AT-11: a screen is finished and the build is green, but the save button is
// wired to a stub. The criterion asks whether the user's task completes, so a
// passing build cannot answer it and the goal must not be judged complete.
func TestBuildEvidenceCannotSettleAJourneyCriterion(t *testing.T) {
	ctx, s, p := proofKindProject(t)
	g, err := s.SetGoal(ctx, p.ID, "Notes app", "user can save a note", "", []model.Criterion{
		{Type: "note_saves", ExpectedValue: "true", RequiredKind: "journey"},
	})
	if err != nil {
		t.Fatal(err)
	}
	if g.Criteria[0].RequiredKind != "journey" {
		t.Fatalf("the demanded kind must survive a round trip: %+v", g.Criteria[0])
	}
	if _, err = s.db.ExecContext(ctx, `INSERT INTO work_items(id,goal_id,type,title,status,weight) VALUES('W1',?,'IMPLEMENT','save screen','DONE',1)`, g.ID); err != nil {
		t.Fatal(err)
	}
	// The gate named after the criterion only compiles the project, and says so.
	if _, err = s.db.ExecContext(ctx, `INSERT INTO verification_results(goal_id,check_type,status,actual_value,evidence_kind,created_at) VALUES(?,'note_saves','PASSED','true','build','now')`, g.ID); err != nil {
		t.Fatal(err)
	}
	detail, err := s.GoalProgressDetail(ctx, g)
	if err != nil {
		t.Fatal(err)
	}
	if detail.Criteria[0].Status != "WRONG_KIND" || detail.Criteria[0].Satisfied {
		t.Fatalf("a build must not settle a journey criterion: %+v", detail.Criteria[0])
	}
	if detail.Complete {
		t.Fatal("the goal must not complete on evidence of the wrong kind")
	}
	if detail.Criteria[0].KindMismatch() == "" {
		t.Fatal("the user needs to be told which kind was asked for and which answered")
	}
	// The same criterion measured by a check that actually carries out the
	// user's task does settle it.
	if _, err = s.db.ExecContext(ctx, `INSERT INTO verification_results(goal_id,check_type,status,actual_value,evidence_kind,created_at) VALUES(?,'note_saves','PASSED','true','journey','now')`, g.ID); err != nil {
		t.Fatal(err)
	}
	detail, err = s.GoalProgressDetail(ctx, g)
	if err != nil {
		t.Fatal(err)
	}
	if detail.Criteria[0].Status != "MET" || !detail.Complete {
		t.Fatalf("journey evidence must settle it: %+v complete=%v", detail.Criteria[0], detail.Complete)
	}
}

// A review gate is a human or model judgement, and the session being judged is
// usually the one that wrote the code. If that judgement settles a criterion
// that asked for an objective check, a run certifies its own work: nothing ever
// compiled and the goal reports complete.
func TestReviewJudgementCannotSettleAnObjectiveCriterion(t *testing.T) {
	ctx, s, p := proofKindProject(t)
	g, err := s.SetGoal(ctx, p.ID, "Service", "ship", "", []model.Criterion{
		{Type: "build_passed", ExpectedValue: "true", RequiredKind: "build"},
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err = s.db.ExecContext(ctx, `INSERT INTO work_items(id,goal_id,type,title,status,weight) VALUES('W1',?,'IMPLEMENT','build it','DONE',1)`, g.ID); err != nil {
		t.Fatal(err)
	}
	// The only evidence for the criterion is a gate that says it judged the
	// change, not one that says it built it.
	if _, err = s.db.ExecContext(ctx, `INSERT INTO verification_results(goal_id,check_type,status,actual_value,evidence_kind,created_at) VALUES(?,'build_passed','PASSED','true','review','now')`, g.ID); err != nil {
		t.Fatal(err)
	}
	detail, err := s.GoalProgressDetail(ctx, g)
	if err != nil {
		t.Fatal(err)
	}
	if detail.Criteria[0].Status != "WRONG_KIND" || detail.Criteria[0].Satisfied {
		t.Fatalf("a judgement must not settle a build criterion: %+v", detail.Criteria[0])

func (s *Store) criterionStatus(ctx context.Context, goalID string, criterion model.Criterion) (CriterionStatus, error) {
	entry := CriterionStatus{Type: criterion.Type, ExpectedValue: criterion.ExpectedValue,
		RequiredKind: criterion.RequiredKind, Status: "NO_EVIDENCE"}
	var measured string
	var stale int
	err := s.db.QueryRowContext(ctx, `SELECT actual_value,status,COALESCE(run_id,''),created_at,COALESCE(stale,0),COALESCE(stale_reason,''),COALESCE(evidence_kind,'') FROM verification_results WHERE goal_id=? AND check_type=? ORDER BY id DESC LIMIT 1`, goalID, criterion.Type).
		Scan(&entry.ActualValue, &entry.CheckStatus, &entry.RunID, &measured, &stale, &entry.StaleReason, &entry.EvidenceKind)
	if errors.Is(err, sql.ErrNoRows) {
		return entry, nil
	}
	if err != nil {
		return entry, err
	}
	entry.HasEvidence = true
	entry.MeasuredAt, _ = time.Parse(time.RFC3339Nano, measured)
	// Stale evidence is not current evidence: the tree or the check it was
	// measured against has changed since, so it cannot satisfy the criterion
	// until it has been re-run.
	if stale == 1 {
		entry.Status, entry.Satisfied = "STALE", false
		return entry, nil
	}
	// Evidence of the wrong kind is not evidence for this criterion. A screen
	// can be finished, the build green, and the save button wired to a stub:
	// the build passing is true and says nothing about whether the user's task
	// completes. Reported separately from UNMET because the fix is different —
	// the check needs replacing, not the code.
	if !policy.EvidenceSatisfies(criterion.RequiredKind, entry.EvidenceKind) {
		entry.Status, entry.Satisfied = "WRONG_KIND", false
		return entry, nil
	}
	met, shortfall := JudgeCriterion(criterion.ExpectedValue, entry.ActualValue)
	entry.Satisfied = entry.CheckStatus == "PASSED" && met
	if entry.Satisfied {
		entry.Status = "MET"
	} else {
		entry.Status = "UNMET"
		entry.Shortfall = shortfall
		if entry.CheckStatus != "PASSED" {
			// The gate itself did not pass, so whatever number it reported is
			// not a measurement of anything. Saying "200ms 를 기대했는데 …"
			// about a crashed check points the reader at the wrong problem.
			entry.Shortfall = "검증이 " + entry.CheckStatus + " 로 끝나 측정값이 없습니다"
		}
	}
	return entry, nil
}

